const listTagRefsForItems = `-- name: ListTagRefsForItems :many
SELECT
  ranked.item_id,
  ranked.tag_id,
  ranked.display,
  ranked.tag_total
FROM (
  SELECT
    it.item_id,
    t.id AS tag_id,
    t.display,
    count(*) OVER (PARTITION BY it.item_id)::int AS tag_total,
    row_number() OVER (
      PARTITION BY it.item_id
      ORDER BY t.display ASC, t.id ASC
    )::int AS rn
  FROM item_tag AS it
  JOIN item AS i ON i.id = it.item_id AND i.user_id = $1
  JOIN tag AS t ON t.id = it.tag_id AND t.user_id = $1
  WHERE it.item_id = ANY($2::uuid[])
    AND i.deleted_at IS NULL
    AND t.deleted_at IS NULL
) AS ranked
WHERE ranked.rn <= 3
ORDER BY
  ranked.item_id ASC,
  ranked.display ASC,
  ranked.tag_id ASC
`

